(* [comment removed for export] *)
Lemma arng_st : forall L RNG st st',
  (forall c, 1 <= c < K_NUM_CLASSES -> get_cls st' c = get_cls st c) -> a_nres st' = a_nres st ->
  Permutation (sec_chunks_of st') (sec_chunks_of st) ->
