Definition AHEAP_P (H : aholes) (L : alayout) (RNG : footprint) (st : astate) (LB : list ablock) (m : amem) : Prop :=
  alayout_ok L /\ arng L RNG st /\ (exists X, AREP H L st X m /\ ablocks L st X LB) /\ ah_fake H L LB m.

