Definition fake_untouched (L : alayout) (W : list (Z * Z)) : Prop :=
  Forall (fun iv => (snd iv <= al_fake L \/ al_fake L + 11571200 <= fst iv)
                 /\ (snd iv <= shad (al_fake L) \/ shad (al_fake L) + shlen 11571200 <= fst iv)
                 /\ (snd iv <= al_dtls L \/ al_dtls L + 4096 <= fst iv)
                 /\ (snd iv <= 0xb14e0 \/ 0xb14e0 + 8 <= fst iv)
                 /\ (snd iv <= 0x5ea908 \/ 0x5ea908 + 16 <= fst iv)
                 /\ (snd iv <= 0x5ea918 \/ 0x5ea918 + 8 <= fst iv)
                 /\ (snd iv <= 0x5ea938 \/ 0x5ea938 + 8 <= fst iv)
                 /\ (snd iv <= 0x149531 \/ 0x149531 + 1 <= fst iv)
                 /\ (snd iv <= 0x147418 \/ 0x147418 + 4 <= fst iv)) W.

Record ahole_laws (H : aholes) : Prop := mkAHL {
  hq_frame : forall L st st' X X' m m' W,
      ah_quar H L st X m -> munch W m m' -> wmono asegs m m' -> quar_untouched L X W -> quar_same st st' X X' ->
      ah_quar H L st' X' m';
  hs_frame : forall L st st' X X' m m' W,
      ah_sec H L st X m -> munch W m m' -> wmono asegs m m' -> sec_untouched L W -> sec_same st st' ->
      ah_sec H L st' X' m';
  hd_frame : forall L m m' W,
      ah_depot H L m -> munch W m m' -> wmono asegs m m' ->
      Forall (fun iv => forall a, fst iv <= a < snd iv ->
                           ~ (0x189848 <= a < 0x5d9890) /\ ~ (al_nodes L <= a < al_nodes L + 1048576)
                           /\ ~ (al_store L <= a < al_store L + 8388608)) W ->
      ah_depot H L m';                                  (* [comment removed for export] *)
  hf_frame : forall L LB m m' W,
      ah_fake H L LB m -> munch W m m' -> wmono asegs m m' -> fake_untouched L W -> ah_fake H L LB m';
  hf_blocks : forall L LB LB' m,
      ah_fake H L LB m -> (forall c F n, In (mkABlock (ABFake c) F n) LB' <-> In (mkABlock (ABFake c) F n) LB) ->
      ah_fake H L LB' m
}.
End CANSEC1.
